            {step.fields && step.fields.map((field) => (
              <div key={field.key} className="input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    className="input-field"
                    required
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="textarea-field"
                    rows={4}
                    required
                  />
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                    required
                  />
                )}
              </div>
            ))}

            {previewSms && (
              <div className="sms-preview-container">
                <div className="sms-preview-label">📱 Your SMS will be:</div>
                <div className="sms-preview-content">{previewSms}</div>
              </div>
            )}

            <div className="registration-actions">
              <button
                type="button"
                onClick={() => goToStep(currentStep - 1)}
                disabled={currentStep === 0 || isLoading || !activationDone}
                className="btn-secondary"
              >
                ⬅ Previous
              </button>

              <button
                type="submit"
                disabled={isLoading || serverStatus === 'error'}
                className={`btn-primary ${isLoading ? 'loading' : ''}`}
              >
                {isLoading ? '⏳ Sending...' : isActivationStep ? '💑 Activate' : '📤 Send'}
              </button>

              {/* Next Button - Always enabled for last step */}
              <button
                type="button"
                onClick={() => {
                  // If on last step and completed, go to menu
                  if (isLastStep && completedSteps.has(currentStep)) {
                    setShowMainMenu(true);
                    setIsLoggedIn(true);
                    return;
                  }
                  // If user exists error, go to menu
                  if (userExistsError) {
                    setCompletedSteps(prev => new Set([...prev, currentStep]));
                    setShowMainMenu(true);
                    setUserExistsError(false);
                    setRegistrationError('');
                    return;
                  }
                  // Otherwise go to next step
                  if (currentStep < STEPS.length - 1) {
                    setCurrentStep(currentStep + 1);
                  }
                }}
                disabled={isLoading || (!isLastStep && !completedSteps.has(currentStep) && !userExistsError)}
                className="btn-secondary"
              >
                {isLastStep && completedSteps.has(currentStep) ? '📋 Go to Menu' : 
                 userExistsError ? '📋 Go to Menu' : 
                 isLastStep ? '📋 Go to Menu' : 'Next ➡'}
              </button>
            </div>
          </form>

          {userExistsError && (
            <div className="user-exists-help">
              <p>💡 You can click <strong>📋 Go to Menu</strong> to proceed to find matches.</p>
            </div>
          )}

          {isLastStep && completedSteps.has(currentStep) && !showUserExistsWarning && (
            <div className="registration-complete-prompt">
